/* Risdel Books Module 33 - Financial Year-End, Period Close & Controls
   Future relational migration reference. Google Sheets remains the active provider. */
CREATE TABLE finance.CloseCycles (Id uniqueidentifier NOT NULL PRIMARY KEY, CloseNumber nvarchar(40) NOT NULL, PeriodId uniqueidentifier NOT NULL, CloseType nvarchar(20) NOT NULL, Status nvarchar(30) NOT NULL, StartedAt datetime2 NOT NULL, StartedBy uniqueidentifier NULL, SubmittedAt datetime2 NULL, SubmittedBy uniqueidentifier NULL, ApprovedAt datetime2 NULL, ApprovedBy uniqueidentifier NULL, ClosedAt datetime2 NULL, ClosedBy uniqueidentifier NULL, ReopenedAt datetime2 NULL, ReopenedBy uniqueidentifier NULL, Notes nvarchar(max) NULL, IsActive bit NOT NULL DEFAULT 1);
CREATE TABLE finance.CloseChecklist (Id uniqueidentifier NOT NULL PRIMARY KEY, CloseCycleId uniqueidentifier NOT NULL, ItemCode nvarchar(30) NOT NULL, ItemName nvarchar(200) NOT NULL, SortOrder int NOT NULL, Status nvarchar(20) NOT NULL, CompletedAt datetime2 NULL, CompletedBy uniqueidentifier NULL, EvidenceReference nvarchar(500) NULL, Notes nvarchar(max) NULL, IsActive bit NOT NULL DEFAULT 1);
CREATE TABLE finance.Accruals (Id uniqueidentifier NOT NULL PRIMARY KEY, AccrualNumber nvarchar(40) NOT NULL, PeriodId uniqueidentifier NOT NULL, Description nvarchar(500) NOT NULL, ExpenseAccountId uniqueidentifier NOT NULL, LiabilityAccountId uniqueidentifier NOT NULL, Amount decimal(18,2) NOT NULL, Status nvarchar(20) NOT NULL, JournalId uniqueidentifier NULL, ReversalDate date NULL, IsActive bit NOT NULL DEFAULT 1);
CREATE TABLE finance.Prepayments (Id uniqueidentifier NOT NULL PRIMARY KEY, PrepaymentNumber nvarchar(40) NOT NULL, Description nvarchar(500) NOT NULL, AssetAccountId uniqueidentifier NOT NULL, ExpenseAccountId uniqueidentifier NOT NULL, OriginalAmount decimal(18,2) NOT NULL, RemainingAmount decimal(18,2) NOT NULL, StartDate date NOT NULL, EndDate date NOT NULL, Frequency nvarchar(20) NOT NULL, Status nvarchar(20) NOT NULL, IsActive bit NOT NULL DEFAULT 1);
